{"ASK_KIDS","role=rescue_clergy|st=friendly,neutral",{"No children of my own, but I've baptized a hundred, and I count them all as mine"}},
{"ASK_KIDS","role=militia|st=friendly,neutral",{"A boy and a girl, and a wife, and the reason I'm still out here is so they can stay in there..."}},
{"ASK_KIDS","reg=civilian,family,worker,rescue|st=friendly,neutral",{"I've got a boy, seven","Two girls, nine and twelve","A baby","A teenager","No kids","Three","My daughter drew a picture of our house","I had a son","Twins","My boy asks when we can go home","She's four","We have five"},false,false,{[1]={{t="he sleeps with a flashlight under his pillow",afterMs=3500},{t="I never take it away",afterMs=3000}},[2]={{t="the older one acts like the mother now",afterMs=3200},{t="it breaks my heart",afterMs=2800}},[3]={{t="eleven months",afterMs=3500},{t="the only one of us who sleeps through the night",afterMs=3000}},[4]={{t="sixteen, and sullen, and wonderful",afterMs=3200},{t="I'd give anything for a slammed door",afterMs=2800}},[5]={{t="I always thought there'd be time",afterMs=3500}},[6]={{t="two with me, one I'm still looking for",afterMs=3200}},[7]={{t="with a fence and a sun and a big smiling dog",afterMs=3500},{t="we never had a dog",afterMs=3000}},[8]={{t="I don't say \"have\" anymore",afterMs=3500},{t="I'm sorry",afterMs=3000}},[9]={{t="they finish each other's sentences",afterMs=3200},{t="it's the one thing that still makes me laugh",afterMs=2800}},[10]={{t="I tell him soon",afterMs=3500},{t="soon is getting heavy",afterMs=3000}},[11]={{t="she thinks the infected are \"sleepy people\"",afterMs=3200},{t="I let her",afterMs=2800}},[12]={{t="and a sixth on the way",afterMs=3500},{t="don't judge, it was a planned surprise",afterMs=3000}}}},
